use std::collections::BTreeSet;
use super::policy_autonomy_copilot_support::{self,PolicyAutonomyCopilotRequest,PolicyAutonomyCopilotReceipt};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.policy_autonomy-signing-workflow-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PolicyAutonomyWorkflowRequest{pub workflow_id:String,pub copilot:PolicyAutonomyCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PolicyAutonomyWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:PolicyAutonomyCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PolicyAutonomyWorkflowError{#[error("invalid policy_autonomy workflow request: {0}")]Invalid(String),#[error("invalid policy_autonomy workflow receipt: {0}")]Receipt(String),#[error("policy_autonomy workflow artifact failed: {0}")]Artifact(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl PolicyAutonomyWorkflowReceipt{pub fn validate(&self)->Result<(),PolicyAutonomyWorkflowError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.checkpoint_seq==0||self.budget_units==0||self.consumed_units>self.budget_units||![&self.replay_identity,&self.workflow_digest].into_iter().all(h){return Err(PolicyAutonomyWorkflowError::Receipt("policy_autonomy workflow identity, budget, locality, or digest is incomplete".into()));}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !o(v){return Err(PolicyAutonomyWorkflowError::Receipt("policy_autonomy workflow vectors are not canonical".into()));}}let ids=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<BTreeSet<_>>();if ids!=p||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(PolicyAutonomyWorkflowError::Receipt("policy_autonomy workflow stages do not partition".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["imaging core scientist","policy_autonomy operator","research program lead"],"behavior":format!("orchestrate resumable policy_autonomy and signing policy_autonomy for {scale}"),"value":"makes policy_autonomy qualification restartable, budgeted, compensating, and replayable without hidden effects","input_schema":"PolicyAutonomyWorkflowRequest1@1","output_schema":"PolicyAutonomyWorkflowReceipt1@1","effects":["schedule:worldgen-policy_autonomy-workflow","block:unsafe-policy_autonomy"],"permissions":["schedule:bounded-policy_autonomy-workflow"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
pub fn schedule(r:&PolicyAutonomyWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<PolicyAutonomyWorkflowReceipt,PolicyAutonomyWorkflowError>{if r.workflow_id.trim().is_empty()||r.stage_order.is_empty()||r.stage_order!={let mut x=r.stage_order.clone();x.sort();x.dedup();x}||r.checkpoint_seq==0||r.budget_units==0||!r.compensation_enabled||!h(&r.replay_identity)||r.copilot.policy_autonomy_request.replay_identity!=r.replay_identity{return Err(PolicyAutonomyWorkflowError::Invalid("policy_autonomy workflow request is invalid".into()))}let completed=r.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();if completed.iter().any(|x|!r.stage_order.contains(x)){return Err(PolicyAutonomyWorkflowError::Invalid("policy_autonomy workflow completed stage is undeclared".into()))}let copilot=policy_autonomy_copilot_support::run(&r.copilot,feature_id,version,scale,require_approval,require_federation).map_err(|e|PolicyAutonomyWorkflowError::Invalid(e.to_string()))?;let pending=r.stage_order.iter().filter(|x|!completed.contains(*x)).cloned().collect::<Vec<_>>();let consumed=(r.copilot.action_order.len()as u64).min(r.budget_units);let compensation=if copilot.disposition=="blocked"{vec![format!("workflow:{}:retain-partial-policy_autonomy-verdict",r.workflow_id)]}else{Vec::new()};let disposition=if copilot.disposition=="blocked"||!compensation.is_empty(){"blocked"}else if pending.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="qualified"{vec![format!("schedule:worldgen-policy_autonomy-workflow:{}",r.workflow_id)]}else{vec!["block:unsafe-policy_autonomy".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"workflow_id":r.workflow_id,"disposition":disposition,"stage_order":r.stage_order,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":compensation,"checkpoint_seq":r.checkpoint_seq,"budget_units":r.budget_units,"consumed_units":consumed,"replay_identity":r.replay_identity,"copilot":copilot.clone(),"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|PolicyAutonomyWorkflowError::Artifact(e.to_string()))?;let out=PolicyAutonomyWorkflowReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:r.workflow_id.clone(),disposition:disposition.into(),stage_order:r.stage_order.clone(),completed_stage_order:completed.iter().cloned().collect(),pending_stage_order:payload["pending_stage_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),compensation_order:payload["compensation_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),checkpoint_seq:r.checkpoint_seq,budget_units:r.budget_units,consumed_units:consumed,replay_identity:r.replay_identity.clone(),copilot,workflow_digest:d.clone(),artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),effect_receipts:effects,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
